CREATE TABLE IF NOT EXISTS public.mentoring_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.mentoring_courses(id) ON DELETE CASCADE, channel_id uuid REFERENCES public.mentoring_channels(id) ON DELETE SET NULL, title text NOT NULL, description text, due_at timestamptz, min_tier integer NOT NULL DEFAULT 1, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.mentoring_assignments ENABLE ROW LEVEL SECURITY; CREATE POLICY "Hub members view assignments" ON public.mentoring_assignments FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id) OR EXISTS (SELECT 1 FROM public.mentoring_hub_members m WHERE m.course_id = mentoring_assignments.course_id AND m.user_id = auth.uid() AND m.banned = false AND m.package_tier >= mentoring_assignments.min_tier)); CREATE POLICY "Mentors admins manage assignments" ON public.mentoring_assignments FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id)) WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id));

CREATE TABLE IF NOT EXISTS public.mentoring_assignment_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES public.mentoring_assignments(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.mentoring_courses(id) ON DELETE CASCADE, user_id uuid NOT NULL, attachment_url text, content text, grade integer, feedback text, reviewed_by uuid, reviewed_at timestamptz, submitted_at timestamptz NOT NULL DEFAULT now(), UNIQUE (assignment_id, user_id)); ALTER TABLE public.mentoring_assignment_submissions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Students view own submission" ON public.mentoring_assignment_submissions FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Mentors admins view all submissions" ON public.mentoring_assignment_submissions FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id));
CREATE POLICY "Students submit assignment" ON public.mentoring_assignment_submissions FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.is_mentoring_hub_member(auth.uid(), course_id));
CREATE POLICY "Students update own submission before review" ON public.mentoring_assignment_submissions FOR UPDATE TO authenticated USING (user_id = auth.uid() AND reviewed_at IS NULL) WITH CHECK (user_id = auth.uid());
CREATE POLICY "Mentors admins grade submissions" ON public.mentoring_assignment_submissions FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id)) WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id));